  1	import { chmodSync } from 'node:fs';
  2	import { getConfigPath } from '../utils/paths.js';
  3	import { readJsonFile, writeJsonFile, FileNotFoundError } from '../storage/json-storage.js';
  4	import type { AppConfig } from './config.types.js';
  5	import {
  6	    DEFAULT_NOTES_CARD_HEIGHT,
  7	    DEFAULT_NOTES_COLUMNS,
  8	} from './config.constants.js';
  9	
 10	const REQUIRED_FIELDS: ReadonlyArray<keyof AppConfig> = ['projectsFolder', 'storageFolder'];
 11	
 12	// MAINTENANCE NOTE: The Pick union below must be extended whenever a new non-optional,
 13	// non-required AppConfig field with a sensible default is added. Add both the key to
 14	// the Pick<AppConfig, ...> type and its value to the object literal below, then update
 15	// loadConfig() to fall back to the new field. See also: constraints.md § Configuration.
 16	export const DEFAULTS: Readonly<Pick<AppConfig, 'cloneDepth' | 'serverPort' | 'gitPollingIntervalSeconds' | 'notesCardHeight' | 'notesColumns'>> = {
 17	    cloneDepth: 50,
 18	    serverPort: 4200,
 19	    gitPollingIntervalSeconds: 30,
 20	    notesCardHeight: DEFAULT_NOTES_CARD_HEIGHT,
 21	    notesColumns: DEFAULT_NOTES_COLUMNS,
 22	};
 23	
 24	/**
 25	 * Loads, validates, and returns the application configuration from `config.json`.
 26	 *
 27	 * **Setup:** Copy `config.dist.json` to `config.json` and fill in the required
 28	 * fields before running the tool.
 29	 *
 30	 * @param configPath Optional absolute path to the config file. Defaults to the
 31	 *   `config.json` in the tool root. Pass a custom path in tests to avoid touching
 32	 *   the real config file.
 33	 * @throws {Error} If `config.json` does not exist (with instruction to copy from
 34	 *   `config.dist.json`).
 35	 * @throws {Error} If any required field is missing, non-string, or empty.
 36	 */
 37	export function loadConfig(configPath?: string): AppConfig {
 38	    const resolvedConfigPath = configPath ?? getConfigPath();
 39	    let raw: Record<string, unknown>;
 40	
 41	    try {
 42	        raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
 43	    } catch (err) {
 44	        if (err instanceof FileNotFoundError) {
 45	            throw new Error(
 46	                `config.json not found at "${resolvedConfigPath}". ` +
 47	                `Copy config.dist.json to config.json and fill in the required fields.`
 48	            );
 49	        }
 50	        throw err;
 51	    }
 52	
 53	    for (const field of REQUIRED_FIELDS) {
 54	        const value = raw[field];
 55	        if (typeof value !== 'string' || value.trim() === '') {
 56	            throw new Error(
 57	                `Configuration error: required field "${field}" must be a non-empty string in config.json.`
 58	            );
 59	        }
 60	    }
 61	
 62	    return {
 63	        projectsFolder: raw['projectsFolder'] as string,
 64	        storageFolder: raw['storageFolder'] as string,
 65	        cloneDepth: typeof raw['cloneDepth'] === 'number' ? raw['cloneDepth'] : DEFAULTS.cloneDepth,
 66	        serverPort: typeof raw['serverPort'] === 'number' ? raw['serverPort'] : DEFAULTS.serverPort,
 67	        gitPollingIntervalSeconds:
 68	            typeof raw['gitPollingIntervalSeconds'] === 'number'
 69	                ? raw['gitPollingIntervalSeconds']
 70	                : DEFAULTS.gitPollingIntervalSeconds,
 71	        gitCredentials: parseGitCredentials(raw['gitCredentials']),
 72	        webserverUrl: typeof raw['webserverUrl'] === 'string' && raw['webserverUrl'].trim() !== ''
 73	            ? raw['webserverUrl'].trim().replace(/\/+$/, '')
 74	            : undefined,
 75	        notesCardHeight: typeof raw['notesCardHeight'] === 'number' ? raw['notesCardHeight'] : DEFAULTS.notesCardHeight,
 76	        notesColumns: typeof raw['notesColumns'] === 'number' ? raw['notesColumns'] : DEFAULTS.notesColumns,
 77	    };
 78	}
