 80	/**
 81	 * Validates and returns the `gitCredentials` value from the raw config.
 82	 *
 83	 * @returns undefined when the field is absent or null.
 84	 * @throws {Error} If the value is present but is not a plain object, or if any
 85	 *   key maps to a non-string or empty-string token.
 86	 */
 87	function parseGitCredentials(value: unknown): Record<string, string> | undefined {
 88	    if (value === undefined || value === null) {
 89	        return undefined;
 90	    }
 91	
 92	    if (typeof value !== 'object' || Array.isArray(value)) {
 93	        throw new Error(
 94	            'Configuration error: "gitCredentials" must be a plain object mapping hostnames to credential strings.'
 95	        );
 96	    }
 97	
 98	    const credentials = value as Record<string, unknown>;
 99	
100	    for (const [key, token] of Object.entries(credentials)) {

101	        if (typeof token !== 'string') {
102	            throw new Error(
103	                `Configuration error: gitCredentials["${key}"] must be a string, got ${typeof token}.`
104	            );
105	        }
106	        if (token === '') {
107	            throw new Error(
108	                `Configuration error: gitCredentials["${key}"] must not be an empty string.`
109	            );
110	        }
111	    }
112	
113	    return credentials as Record<string, string>;
114	}
