116	/**
117	 * Reads `config.json`, sets or removes a single top-level field, and writes the
118	 * file back via `writeJsonFile()`. All other fields — including `_instructions`
119	 * — are preserved.
120	 *
121	 * @param field - The top-level key to modify (e.g. `"gitCredentials"`).
122	 * @param value - The value to set, or `undefined` to remove the field.
123	 * @param configPath - Optional absolute path to the config file. Defaults to
124	 *   the tool-root `config.json`.
125	 * @throws {Error} If `config.json` cannot be read or written.
126	 */
127	export function saveConfigField(
128	    field: string,
129	    value: unknown,
130	    configPath?: string,
131	): void {
132	    const resolvedConfigPath = configPath ?? getConfigPath();
133	    const raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
134	
135	    if (value === undefined) {
136	        delete raw[field];
137	    } else {
138	        raw[field] = value;
139	    }
140	
141	    writeJsonFile(resolvedConfigPath, raw);
142	
143	    // config.json may contain plaintext PATs in gitCredentials — restrict
144	    // file permissions to owner-only on POSIX systems.
145	    if (process.platform !== 'win32') {
146	        chmodSync(resolvedConfigPath, 0o600);
147	    }
148	}

